import{_ as t,o as i,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-06-05 :: Ceph Developer Monthly part 1","description":"","frontmatter":{"title":"2019-06-05 :: Ceph Developer Monthly part 1","date":"2019-06-05T00:00:00.000Z","updated":"2019-06-07T00:00:00.000Z","tags":["Ceph","分布式存储","RBD","云迁移","快照管理","灾难恢复","集群监控","降级支持"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_1.md","filePath":"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_1.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-06-05_-_-_Ceph_Developer_Monthly_part_1.md"};function n(e,l,p,_,g,a){return i(),o("div",null,[...l[0]||(l[0]=[s("<p><strong>会议主题</strong>： Ceph 存储系统开发讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Lily, Justin, Jason, Josh, Jr., Patrick, Aashish, Casey 等</p><p><strong>会议内容</strong>：</p><p><strong>一、RBD 云迁移功能</strong></p><ul><li><strong>背景</strong>： RBD 云迁移功能自 Jewel 版本以来一直存在，但使用率不高，存在 journaling 和可路由网络问题。</li><li><strong>改进方案</strong>： <ul><li>提供多种可选镜像模式，包括基于周期性计划的自动快照和按需迁移。</li><li>扩展跨集群实时迁移功能，以加快迁移过程。</li><li>考虑使用 Radios 代理或类似技术来解决可路由网络问题。</li><li>考虑使用推模型而不是拉模型来提高效率。</li><li>考虑使用伪存储桶来实现多站点 RGW 复制。</li></ul></li></ul><p><strong>二、快照管理</strong></p><ul><li><strong>背景</strong>： 用户需要更灵活的快照管理功能。</li><li><strong>改进方案</strong>： <ul><li>提供基于子目录的快照计划，包括定时快照和保留策略。</li><li>提供独立的快照计划和修剪计划，以提高灵活性。</li><li>考虑使用卷名称而不是文件系统名称来指定快照路径。</li><li>考虑限制快照创建速率，以避免性能问题。</li></ul></li></ul><p><strong>三、灾难恢复</strong></p><ul><li><strong>背景</strong>： 用户需要更简单的灾难恢复解决方案。</li><li><strong>改进方案</strong>： <ul><li>提供基于快照的灾难恢复模式，包括源目录、目标目录和同步频率。</li><li>提供更高效的快照复制机制，例如使用 rsync 或类似工具。</li><li>提供回滚功能，以便在灾难发生时恢复数据。</li></ul></li></ul><p><strong>四、集群进度监控</strong></p><ul><li><strong>背景</strong>： 用户需要更详细的集群进度监控信息。</li><li><strong>改进方案</strong>： <ul><li>扩展进度模块，以跟踪更广泛的集群活动，例如 OSD 备份、数据恢复和负载均衡。</li><li>为进度事件添加完成时间估算，以便用户了解恢复进度。</li></ul></li></ul><p><strong>五、降级支持</strong></p><ul><li><strong>背景</strong>： 用户需要支持降级到旧版本。</li><li><strong>改进方案</strong>： <ul><li>使用现有的升级测试套件来测试降级。</li><li>更小心地处理向后兼容性，以避免破坏现有集群。</li></ul></li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Jason 将准备更详细的提案，包括新的镜像模式和灾难恢复功能。</li><li>Lily 和 Justin 将继续改进快照管理功能。</li><li>Josh 和 Jr. 将继续改进进度模块。</li><li>Casey 将考虑降级支持。</li></ul><p><strong>其他事项</strong>：</p><ul><li>会议讨论了如何改进 Ceph 的文档和测试。</li><li>会议讨论了如何提高 Ceph 的性能和可靠性。</li></ul>",18)])])}const d=t(r,[["render",n]]);export{h as __pageData,d as default};
